const SYSTEMS=[
  {id:'friction',name:'Harm Friction OS',num:'01',summary:'Map the harmful workflow and insert selective friction before irreversible action.',mechanism:'Analyze intent → preparation → access → opportunity → action → concealment → reward → imitation, then add safeguards where they produce high protective value with low burden on legitimate use.',implementation:['Map the actual workflow before choosing controls.','Add safer defaults, dual authorization, cooling-off periods or rate limits only at consequential stages.','Preserve an emergency or legitimate-use bypass with logging and review.','Measure burden on ordinary users alongside prevented or interrupted incidents.'],safeguards:['Do not maximize friction everywhere.','Avoid controls that punish protected speech or legitimate dissent.','Keep appeal and correction paths.'],metrics:['interrupted harmful attempts','false-positive burden','time-to-safe-escalation','bypass review quality'],levers:['friction','detection','reward'],tags:['prevention','workflow','safer defaults']},
  {id:'intergenerational',name:'Intergenerational Safeguarding Dashboard',num:'02',summary:'Track environmental pressures and protective factors that shape repetition across time.',mechanism:'Treat transmission as a systems problem: exposure and reinforcement can be interrupted by stable relationships, material security, emotional regulation, belonging, mentorship and repair.',implementation:['Track trends at group/system level.','Pair every pressure indicator with a protective-capacity indicator.','Review whether interventions reduce exposure and increase safe alternatives.','Include youth and caregiver perspectives without forcing disclosure.'],safeguards:['Never rank children or families by presumed future harm.','Do not infer causation from adversity counts.','Minimize sensitive data.'],metrics:['trusted-adult access','stability indicators','repair participation','protective-factor coverage'],levers:['transmission','detection'],tags:['generations','protective factors','resilience']},
  {id:'integrity',name:'Integrity-by-Design Toolkit',num:'03',summary:'Redesign high-consequence processes so abuse, corruption and concealment require more coordination and leave more evidence.',mechanism:'Use separation of powers, auditability, conflicts disclosure, evidence retention, independent review and meaningful appeal as structural controls rather than relying only on personal virtue.',implementation:['Identify unilateral decision points.','Separate initiation, approval, review and appeal where stakes justify it.','Create tamper-evident logs without over-collecting personal data.','Make conflicts of interest and exceptions visible.'],safeguards:['Oversight bodies also need oversight.','Audit logs should not become surveillance archives.','Retention periods should be explicit.'],metrics:['unreviewed exceptions','appeal resolution','conflict disclosures','control bypass frequency'],levers:['friction','detection'],tags:['governance','audit','due process']},
  {id:'signals',name:'Early Signal Commons',num:'04',summary:'Aggregate weak signals early enough to review system conditions before severe harm becomes normalized.',mechanism:'Combine categories and counts—incidents, absenteeism, turnover, anonymous concerns, service failures—while avoiding person-level accusation or automated guilt decisions.',implementation:['Collect minimum aggregate data.','Set review thresholds before looking at results.','Use human review to distinguish noise, inequity and real system failures.','Publish what data is collected, why and for how long.'],safeguards:['A signal triggers inquiry, not punishment.','Suppress tiny groups where re-identification is plausible.','Do not reward report volume.'],metrics:['time-to-review','signal corroboration rate','privacy incidents','corrective actions completed'],levers:['detection'],tags:['weak signals','privacy','early warning']},
  {id:'exploitability',name:'Exploitability Surface Mapper',num:'05',summary:'Map conditions that make exploitation easy: dependency, opacity, scarcity, isolation and concentrated power.',mechanism:'Borrow the attack-surface idea from security engineering, but apply it to systems and environments rather than scoring people.',implementation:['Map where users cannot realistically exit or appeal.','Identify information asymmetry and resource dependency.','Reduce single-gatekeeper power.','Add independent channels and transparent rules.'],safeguards:['Do not label populations as inherently vulnerable or dangerous.','Separate structural conditions from personal traits.'],metrics:['single-point dependencies','appeal accessibility','information parity','exit-option quality'],levers:['friction','detection','reward'],tags:['attack surface','dependency','power']},
  {id:'rewards',name:'Reward Reversal Engine',num:'06',summary:'Change the payoff structure so harmful conduct loses status, money or attention while constructive alternatives gain them.',mechanism:'Identify what a harmful pattern actually earns—attention, dominance, belonging, money, revenge—then design credible pro-social routes to the same underlying human need where possible.',implementation:['Map the existing reinforcement loop.','Remove amplification without creating forbidden-topic lists.','Reward verified repair, mentorship and useful contribution.','Test for gaming and perverse incentives.'],safeguards:['Do not create coercive social-credit systems.','Avoid public shame as a substitute for accountability.','Keep incentives transparent.'],metrics:['harm-amplification rate','repair participation','positive contribution uptake','gaming incidents'],levers:['reward','transmission'],tags:['incentives','status','attention']},
  {id:'narrative',name:'Narrative Immunity OS',num:'07',summary:'Teach recognition of manipulative narrative patterns before they normalize cruelty or retaliatory thinking.',mechanism:'Expose rhetorical moves such as dehumanization, manufactured urgency, purity framing, collective blame, revenge loops and moral disengagement, while preserving open inquiry and disagreement.',implementation:['Teach pattern recognition with diverse examples.','Pair critique with steelmanning and source verification.','Practice slowing down identity-based claims.','Show how messages mutate across networks.'],safeguards:['Do not label disagreement as misinformation by default.','Do not infer speaker intent from keywords.','Keep political and cultural examples plural and sourced.'],metrics:['source-checking behavior','de-escalation choices','recognition accuracy in training','false-positive cue rate'],levers:['transmission','reward','detection'],tags:['media literacy','scapegoating','rhetoric']},
  {id:'accountability',name:'Restorative Accountability Ledger',num:'08',summary:'Preserve accountability, repair and recurrence prevention without making stigma permanent.',mechanism:'Track acknowledgement, evidence status, restitution, corrective action, safeguards, recurrence and reintegration as distinct states.',implementation:['Use pseudonymous IDs in low-security contexts.','Separate allegations from established findings.','Record concrete repair commitments and safeguards.','Review recurrence without indefinite data retention.'],safeguards:['Not a public blacklist.','Do not treat completion of a form as proof of repair.','Keep lawful due process and professional procedures.'],metrics:['repair commitments completed','recurrence after safeguards','time to resolution','appeal/correction events'],levers:['detection','reward','transmission'],tags:['repair','accountability','reintegration']},
  {id:'simulation',name:'Safeguarding Simulation Lab',num:'09',summary:'Rehearse system failures and intervention choices before real crises force improvisation.',mechanism:'Use hypothetical scenarios to reveal how opportunity, reward, concealment, transmission and protective capacity interact across roles.',implementation:['Model assumptions explicitly.','Let different roles see different constraints.','Compare multiple interventions rather than a single “correct” answer.','Debrief unintended consequences.'],safeguards:['Simulation output is not prediction.','Do not train offensive tactics in operational detail.','Prefer prevention, de-escalation and recovery scenarios.'],metrics:['scenario coverage','identified failure modes','mitigations adopted','post-exercise revisions'],levers:['friction','detection','reward','transmission'],tags:['rehearsal','scenario','systems thinking']},
  {id:'ecosystem',name:'Protective Ecosystem Command Center',num:'10',summary:'Coordinate the protective network instead of assigning safeguarding to one institution.',mechanism:'Connect family, education, health, housing, employment, justice, community, media, technology and governance around shared prevention and repair outcomes.',implementation:['Map responsibilities and handoff gaps.','Define what information actually needs to cross boundaries.','Track protective capacity, not only incident counts.','Use shared review cycles and community feedback.'],safeguards:['Do not create a universal personal dossier.','Use purpose-limited data sharing.','Retain local autonomy where centralization adds little value.'],metrics:['handoff completion','protective-service access','unowned risks','cross-sector corrective actions'],levers:['friction','detection','reward','transmission'],tags:['coordination','capacity','ecosystem']}
];

const STORIES=[
 {id:'chain',title:'The Generation That Broke the Chain',audience:['families','schools','general'],premise:'A family reconstructs 150 years of retaliation and discovers that each generation thought it was merely answering the previous wrong.',lesson:'Inherited scripts can be interrupted without denying the original harm.',mechanism:'Makes retaliatory transmission visible and gives refusal-to-repeat narrative status.',activity:'Map a fictional conflict across three generations. Identify the first plausible off-ramp in each generation.',connection:['Intergenerational Dashboard','Restorative Accountability Ledger','Narrative Immunity OS']},
 {id:'city',title:'The City Where Harm Became Inconvenient',audience:['communities','institutions','general'],premise:'A near-future city redesigns procedures so exploitation requires more coordination, leaves more evidence and yields less reward.',lesson:'Architecture can shape behavior without requiring perfect people.',mechanism:'Turns abstract prevention into concrete civic design choices.',activity:'Redesign one everyday workflow so legitimate use stays easy while harmful use gains friction.',connection:['Harm Friction OS','Integrity-by-Design Toolkit','Exploitability Surface Mapper']},
 {id:'bully',title:'The Last Bully',audience:['schools','families'],premise:'A school removes the audience and status rewards of bullying while creating alternative routes to belonging and recognition.',lesson:'Changing reinforcement can outperform cycles of humiliation.',mechanism:'Separates accountability from counter-humiliation.',activity:'List the visible and invisible rewards a fictional bullying pattern receives; design non-harmful substitutes.',connection:['Reward Reversal Engine','Early Signal Commons','Restorative Accountability Ledger']},
 {id:'inheritance',title:'The Inheritance',audience:['families','general'],premise:'At adulthood, people inherit a family behavioral archive alongside property, revealing unresolved patterns before they repeat.',lesson:'Context can be transmitted without transmitting shame.',mechanism:'Reframes family history as protective knowledge rather than destiny.',activity:'Create a fictional inheritance card containing one repeating conflict, one repair skill and one protective tradition.',connection:['Intergenerational Dashboard','Evidence & Provenance Ledger']},
 {id:'reputation',title:'The Reputation Economy Collapses',audience:['institutions','communities','general'],premise:'Algorithms and organizations stop rewarding outrage, domination and spectacle and begin recognizing teaching, repair and verified contribution.',lesson:'Attention systems are behavioral infrastructure.',mechanism:'Makes hidden reward functions narratively visible.',activity:'Audit the reward function of a fictional platform or workplace and redesign three incentives.',connection:['Reward Reversal Engine','Narrative Immunity OS']},
 {id:'museum',title:'The Museum of Bad Ideas',audience:['schools','general'],premise:'Future children tour exhibits about once-normal harmful practices, then discover that their own era also has blind spots.',lesson:'Moral progress requires humility about present norms.',mechanism:'Creates historical distance without assuming the future is perfect.',activity:'Design one museum exhibit from the future about a current practice, then write the strongest defense of that practice before critiquing it.',connection:['Narrative Immunity OS','Safeguarding Simulation Lab']},
 {id:'guardian',title:'The Guardian Algorithm That Refused to Judge',audience:['institutions','general'],premise:'An AI asked to identify dangerous people refuses and instead maps dangerous environmental conditions such as unaccountable power and extreme isolation.',lesson:'System risk can be reduced without pretending to predict individual guilt.',mechanism:'Directly challenges seductive but unsafe person-scoring approaches.',activity:'Convert five person-level risk questions into system-level design questions.',connection:['Exploitability Surface Mapper','Integrity-by-Design Toolkit','Early Signal Commons']},
 {id:'village',title:'The Village That Remembered Everything Except Shame',audience:['communities','institutions','general'],premise:'A community keeps lessons from institutional failures while ordinary names fade after accountability and repair are complete.',lesson:'Societies can preserve memory without preserving vendetta.',mechanism:'Separates collective learning from permanent personal stigma.',activity:'Design a retention policy for lessons, safeguards and personal identifiers after a fictional resolved incident.',connection:['Restorative Accountability Ledger','Evidence & Provenance Ledger']},
 {id:'seven',title:'Seven Seconds Before',audience:['schools','families','general'],premise:'Each chapter begins seven seconds before a harmful decision and explores the tiny environmental changes that could create another exit.',lesson:'Prevention often lives in the design of moments before irreversibility.',mechanism:'Makes friction, pause and off-ramps emotionally concrete.',activity:'Pick a fictional conflict and create three seven-second interventions: environmental, relational and interface-based.',connection:['Harm Friction OS','Safeguarding Simulation Lab']},
 {id:'children',title:'The Children Who Redesigned Civilization',audience:['schools','families','communities','institutions','general'],premise:'Children are asked to design a civilization where hurting people is difficult, helping is easy and mistakes do not become destinies; adults start prototyping the designs.',lesson:'Youth participation can surface assumptions adults no longer notice.',mechanism:'Transforms children from passive beneficiaries into constrained co-designers.',activity:'Run a child-safe design sprint: “What would make helping easier here?” Adults may only ask clarifying questions during the first round.',connection:['Protective Ecosystem Command Center','Reward Reversal Engine','Harm Friction OS']}
];

const GUIDES=[
 {title:'Designing selective friction',one:'Protective friction adds a pause, second check or safer default at the exact point where a harmful action becomes consequential.',steps:['Map the legitimate workflow first.','Mark irreversible or high-consequence steps.','Add the lightest effective safeguard.','Measure both interruption and user burden.'],advanced:'Use threat modeling, human-factors analysis and reversible control design. Separate authentication friction from deliberation friction and authorization friction.',impl:'Represent workflows as stages with control hooks. Log only what is necessary. Test bypass, failure recovery, accessibility and legitimate emergency use.'},
 {title:'Weak-signal detection without surveillance',one:'Look for system patterns early, but aggregate them so a dashboard does not become a dossier about individuals.',steps:['Define the minimum category/count data.','Set privacy thresholds.','Predefine what triggers review.','Require human corroboration before consequential action.'],advanced:'Consider k-anonymity-style suppression, retention limits, differential privacy for larger deployments and bias audits across reporting channels.',impl:'Keep raw intake separate from aggregate dashboards. Use role-based access, purpose limitation, review logs and deletion schedules.'},
 {title:'Intergenerational transmission as a system',one:'Repeated harm is not destiny. Environments can amplify or interrupt learned patterns, stress responses, norms and relationship expectations.',steps:['Map pressures without diagnosing people.','Map protective relationships and resources.','Choose one pressure to reduce and one protective factor to grow.','Review change over time.'],advanced:'Distinguish exposure, reinforcement, modeling, material stress and social norms. Avoid causal claims from simple adversity counts.',impl:'Use aggregate longitudinal indicators where possible; pair every pressure metric with at least one protective-capacity metric.'},
 {title:'Restorative accountability',one:'Accountability asks what happened, what evidence supports it, what must be repaired and what prevents recurrence. It need not require permanent humiliation.',steps:['Separate report from established finding.','Define repair obligations.','Add safeguards.','Review recurrence and reintegration.'],advanced:'Use proportionality, procedural fairness, victim/survivor agency, legal obligations and safety planning appropriate to the context.',impl:'Model status transitions separately: report, review, finding, repair, safeguards, closure, recurrence. Never collapse them into one score.'},
 {title:'Narrative immunity',one:'Teach people to notice manipulative rhetorical patterns while preserving disagreement, open inquiry and source checking.',steps:['Identify collective blame or dehumanization.','Slow manufactured urgency.','Check sources and missing context.','Reframe toward concrete behaviors and verifiable claims.'],advanced:'Combine inoculation theory, media literacy, steelmanning, uncertainty calibration and social-norm interventions without creating ideological conformity tests.',impl:'Text heuristics should return cues for review, never truth labels or inferred intent. Keep examples plural and culturally contextualized.'},
 {title:'Local-first data sovereignty',one:'Keep essential planning usable on-device and make export/import explicit so users are not trapped in a service.',steps:['Store structured state locally.','Version the schema.','Offer validated JSON export/import.','Explain what is and is not synchronized.'],advanced:'Use IndexedDB for structured records, localStorage only for small preferences, and explicit migrations for schema changes.',impl:'Treat offline and online state separately. Service workers cache app assets, not magically every live API. Preserve user data through failed optional-feature initialization.'},
 {title:'Progressive multiplayer',one:'Collaboration should enhance the tool, not become a single point of failure.',steps:['Start with local state.','Add same-origin collaboration.','Add authenticated/authorized server or P2P transport only where useful.','Define disconnect and conflict behavior.'],advanced:'P2P lowers central dependency but complicates moderation, durable membership, NAT traversal, abuse controls and authoritative history.',impl:'Keep message schemas transport-independent. Never send sensitive records to peers by default. Provide leave/reset controls and visible connection state.'},
 {title:'Evidence and provenance',one:'A credible tool shows where a claim came from and whether it is fact, inference, hypothesis, simulation, metaphor or fiction.',steps:['Label the claim type.','Attach the source.','Record review status.','Retain contradictions and superseded claims rather than silently rewriting history.'],advanced:'For serious deployments add source snapshots, hashes, reviewer identity/role, methodology fields and evidence-quality criteria.',impl:'Use immutable IDs and revision history. Hashes establish integrity of bytes, not truth or authorship.'}
];

const EXPOSURES=['exposure to violence or intimidation','unstable housing or repeated displacement','food/material insecurity','social isolation','normalization of humiliation','coercive or retaliatory norms','educational exclusion','lack of safe grievance channels'];
const PROTECTIVE=['trusted adult / mentor access','stable housing and routines','food/material security','emotional regulation skills','safe conflict-resolution practice','belonging and community participation','accessible education','credible repair and grievance pathways'];
const INTEGRITY_RISKS=[['unilateral','One person can make a high-consequence decision without review.'],['erasable','Important records can be altered or disappear without trace.'],['retaliation','People raising concerns depend on the same authority they report.'],['opaque','Rules, exceptions or reasons are not visible to affected people.'],['conflict','Conflicts of interest can remain undisclosed.'],['noappeal','There is no practical independent appeal or correction path.']];
const EXPLOIT_FACTORS=['Dependency on one gatekeeper','Information asymmetry','Concentrated authority','Material scarcity / desperation','Social isolation','Institutional opacity','Weak grievance channels'];
const SIM_VARS=[['opportunity','Opportunity'],['reward','Harmful reward'],['concealment','Concealment'],['transmission','Social transmission'],['friction','Protective friction'],['detection','Proportionate detection'],['accountability','Accountability / repair'],['protective','Protective capacity']];
const ECO_DOMAINS=['Family / caregivers','Education','Health / wellbeing supports','Housing / material security','Employment / livelihoods','Justice / accountability','Community / belonging','Media / information','Technology / platforms','Governance / public institutions'];
const FRICTION_STAGES=['Preparation','Access','Opportunity','Action','Concealment','Reward','Imitation'];

const DEFAULT_STATE={schemaVersion:1,signals:[],cases:[],evidence:[],notes:[],selectedSystems:[],progress:{xp:0,seeds:0,quests:{}},lastSaved:null,plannerRuns:[],storyRuns:[],settings:{}};
let state=structuredClone(DEFAULT_STATE);
let saveTimer=null, roomChannel=null, p2pRoom=null, p2pSend=null;

const DB={
  db:null,
  async open(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window))return reject(new Error('IndexedDB unsupported'));const req=indexedDB.open('safeguarding-nextgen-os',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('kv'))req.result.createObjectStore('kv')};req.onsuccess=()=>{this.db=req.result;resolve(this.db)};req.onerror=()=>reject(req.error)})},
  async get(key){if(!this.db)return null;return new Promise((resolve,reject)=>{const tx=this.db.transaction('kv','readonly');const r=tx.objectStore('kv').get(key);r.onsuccess=()=>resolve(r.result??null);r.onerror=()=>reject(r.error)})},
  async set(key,val){if(!this.db)return;return new Promise((resolve,reject)=>{const tx=this.db.transaction('kv','readwrite');tx.objectStore('kv').put(val,key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
};

function mergeState(raw){const merged=structuredClone(DEFAULT_STATE);if(!raw||typeof raw!=='object')return merged;for(const k of Object.keys(merged)){if(raw[k]!==undefined)merged[k]=raw[k]}if(!merged.progress||typeof merged.progress!=='object')merged.progress=structuredClone(DEFAULT_STATE.progress);if(!merged.progress.quests)merged.progress.quests={};return merged}
async function persist(immediate=false){clearTimeout(saveTimer);const run=async()=>{state.lastSaved=nowIso();try{await DB.set('workspace',state)}catch(e){console.warn('Persist failed',e)}renderHud()};if(immediate)return run();saveTimer=setTimeout(run,250)}
function recordCount(){return state.signals.length+state.cases.length+state.evidence.length+state.plannerRuns.length+state.storyRuns.length}
function award(id,xp=15,seeds=1){if(state.progress.quests[id])return;state.progress.quests[id]=true;state.progress.xp+=xp;state.progress.seeds+=seeds;persist();renderHud()}
function levelInfo(){const level=Math.floor(state.progress.xp/100)+1;const cur=state.progress.xp%100;return{level,cur}}

function renderNav(){
 const groups=[...new Set(ROUTES.map(r=>r.group))];
 $('#side-nav').innerHTML=groups.map(g=>`<div class="group">${esc(g)}</div>${ROUTES.filter(r=>r.group===g).map(r=>`<a href="#${r.id}" data-nav="${r.id}"><span>${r.icon}</span><span>${esc(r.label)}</span></a>`).join('')}`).join('');
 $('#top-nav').innerHTML=ROUTES.filter(r=>r.top).map(r=>`<a href="#${r.id}" data-nav="${r.id}">${esc(r.label)}</a>`).join('');
}
function routeTo(id){if(!ROUTES.some(r=>r.id===id))id='overview';$$('.route').forEach(s=>s.classList.toggle('active',s.dataset.route===id));$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===id));const r=ROUTES.find(x=>x.id===id);$('#breadcrumbs').textContent=`Safeguarding Next-Gen / ${r.label}`;document.body.classList.remove('drawer-open','right-drawer-open');$('#drawer-toggle')?.setAttribute('aria-expanded','false');try{$('#workspace').focus({preventScroll:true})}catch{};if(location.hash.slice(1)!==id)history.replaceState(null,'',`#${id}`)}
function routeFromHash(){routeTo(location.hash.slice(1)||'overview')}

function renderOverview(){
 $('#overview-stats').innerHTML=[['10','operating systems'],['10','story engines'],['6','prevention levers'],['0','required cloud accounts']].map(([n,l])=>`<div class="stat"><strong>${n}</strong><span>${l}</span></div>`).join('');
 const chain=[['1','Reduce opportunity','Selective friction, safer defaults, fewer unreviewable single points of power.'],['2','Increase visibility','Proportionate detection, aggregate signals, evidence preservation and independent review.'],['3','Remove harmful reward','Reduce payoff from attention, money, dominance, belonging or concealment.'],['4','Interrupt imitation','Narrative immunity, social norms, off-ramps and non-harmful status routes.'],['5','Strengthen repair','Acknowledgement, restitution, safeguards, recurrence review and reintegration.'],['6','Transmit protection','Mentorship, stable supports, skills, community memory and youth participation.']];
 $('#prevention-chain').innerHTML=chain.map(([n,t,d])=>`<div class="timeline-item"><div class="step">${n}</div><div><strong>${t}</strong><div class="muted">${d}</div></div></div>`).join('');
}

function renderSystems(){
 const q=($('#system-search')?.value||'').toLowerCase();
 const visible=SYSTEMS.filter(s=>[s.name,s.summary,s.mechanism,...s.tags].join(' ').toLowerCase().includes(q));
 $('#system-list').innerHTML=visible.map(s=>`<article class="panel system-card" data-number="${s.num}">
   <div class="section-split"><div><p class="eyebrow">System ${s.num}</p><h2>${esc(s.name)}</h2></div><label class="checkline"><input class="system-select" data-system="${s.id}" type="checkbox" ${state.selectedSystems.includes(s.id)?'checked':''}> constellation</label></div>
   <p>${esc(s.summary)}</p><div class="tag-row">${s.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>
   <div class="levers" title="Prevention levers">${['friction','detection','reward','transmission'].map(l=>`<span class="lever ${s.levers.includes(l)?'on':''}" title="${l}"></span>`).join('')}</div>
   <details><summary>Mechanism, implementation & safeguards</summary><p>${esc(s.mechanism)}</p><h3>Implementation</h3><ul>${s.implementation.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Anti-inversion safeguards</h3><ul>${s.safeguards.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Useful measures</h3><div class="chip-cloud">${s.metrics.map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div><p><a href="#${s.id}">Open module →</a></p></details>
 </article>`).join('')||'<p class="muted">No systems match that search.</p>';
 $$('.system-select').forEach(cb=>cb.addEventListener('change',()=>{const id=cb.dataset.system;if(cb.checked&&!state.selectedSystems.includes(id))state.selectedSystems.push(id);if(!cb.checked)state.selectedSystems=state.selectedSystems.filter(x=>x!==id);persist();renderConstellation()}));
 renderConstellation();
}
function renderConstellation(){
 const svg=$('#system-constellation');if(!svg)return;const selected=SYSTEMS.filter(s=>state.selectedSystems.includes(s.id));const nodes=selected.length?selected:SYSTEMS.slice(0,6);const cx=450,cy=215,r=155;let html='';
 nodes.forEach((a,i)=>nodes.slice(i+1).forEach((b,j)=>{const ii=i,jj=i+1+j;const ax=cx+r*Math.cos((i/nodes.length)*Math.PI*2),ay=cy+r*Math.sin((i/nodes.length)*Math.PI*2);const bx=cx+r*Math.cos((jj/nodes.length)*Math.PI*2),by=cy+r*Math.sin((jj/nodes.length)*Math.PI*2);const shared=a.levers.filter(x=>b.levers.includes(x)).length;if(shared)html+=`<line class="edge ${shared>1?'strong':''}" x1="${ax}" y1="${ay}" x2="${bx}" y2="${by}" opacity="${.2+shared*.18}"/>`}));
 nodes.forEach((n,i)=>{const x=cx+r*Math.cos((i/nodes.length)*Math.PI*2),y=cy+r*Math.sin((i/nodes.length)*Math.PI*2);html+=`<g><circle class="node-circle" cx="${x}" cy="${y}" r="31"/><text x="${x}" y="${y-2}" text-anchor="middle" fill="currentColor" font-size="12" font-weight="800">${n.num}</text><text x="${x}" y="${y+48}" text-anchor="middle" fill="currentColor" font-size="11">${esc(n.name.replace(/ OS| Toolkit| Dashboard| Engine| Mapper| Ledger| Lab| Command Center/,'')).slice(0,22)}</text></g>`});
 html+=`<g><circle cx="${cx}" cy="${cy}" r="54" fill="var(--panel2)" stroke="var(--violet)"/><text x="${cx}" y="${cy-4}" text-anchor="middle" fill="currentColor" font-size="13" font-weight="800">Protective</text><text x="${cx}" y="${cy+14}" text-anchor="middle" fill="currentColor" font-size="13" font-weight="800">Capacity</text></g>`;svg.innerHTML=html;
}

function initFriction(){
 $('#friction-stages').innerHTML=`<legend>Where is the pathway easiest?</legend>${FRICTION_STAGES.map(s=>`<label class="checkline"><input type="checkbox" value="${s}" ${['Opportunity','Concealment','Reward'].includes(s)?'checked':''}> ${s}</label>`).join('')}`;
 $('#friction-pathway').innerHTML=['Intent','Preparation','Access','Opportunity','Action','Concealment','Reward','Imitation'].map((x,i)=>`<div class="timeline-item"><div class="step">${i+1}</div><div><strong>${x}</strong><div class="muted">${['Motivation exists; focus on safe alternatives rather than thought policing.','Resources or coordination begin.','Permissions, tools or proximity become available.','Context allows action with limited interruption.','Consequential behavior occurs.','Evidence can be hidden, erased or normalized.','Money, status, attention, belonging or control reinforces the pattern.','Others learn that the behavior works or is tolerated.'][i]}</div></div></div>`).join('');
}
function runFriction(){const stages=$$('#friction-stages input:checked').map(x=>x.value);const workflow=$('#friction-workflow').value.trim()||'this workflow';const concern=$('#friction-concern').value;const patterns={Preparation:['add an explicit preparation checkpoint for high-consequence actions','make policy/consent requirements visible before resources are committed'],Access:['use least privilege, time-bounded access and independent approval where stakes justify it','ensure legitimate emergency access remains possible and reviewed'],Opportunity:['change defaults, staffing or environment so isolated unreviewable opportunities shrink','add safe bystander/escalation routes'],Action:['insert confirmation, cooling-off or two-person review for irreversible actions','provide de-escalation/off-ramp choices at the moment of action'],Concealment:['use proportionate tamper-evident records and retention rules','separate record custody from the authority being reviewed'],Reward:['remove attention/status/money reinforcement and reward verified repair or contribution','audit whether sanctions themselves create notoriety'],Imitation:['teach narrative/social-norm resistance and visibly model alternative status routes','publish system lessons without glamorizing harmful tactics']};const out=stages.length?stages.flatMap(s=>patterns[s].map(p=>`<div class="record"><strong>${s}</strong><p>${esc(p)} for ${esc(workflow)}.</p></div>`)):['<p class="muted">Select at least one pathway stage.</p>'];out.push(`<div class="notice"><strong>Concern lens:</strong> ${esc(concern)}. Validate these controls with affected users; measure legitimate-user burden and false positives, not only interruption.</div>`);$('#friction-output').innerHTML=out.join('');award('friction',20,1)}

function initIntergenerational(){
 $('#exposure-checks').innerHTML=EXPOSURES.map((x,i)=>`<label class="checkline"><input class="exposure" type="checkbox" value="${i}"> ${esc(x)}</label>`).join('');
 $('#protective-checks').innerHTML=PROTECTIVE.map((x,i)=>`<label class="checkline"><input class="protective" type="checkbox" value="${i}"> ${esc(x)}</label>`).join('');
 $$('.exposure,.protective').forEach(x=>x.addEventListener('change',updateTransmission));updateTransmission();
}
function updateTransmission(){const e=$$('.exposure:checked').length,p=$$('.protective:checked').length;const idx=Math.round(clamp((e*14)-(p*9)+20,0,100));$('#transmission-score').textContent=idx;$('#transmission-label').textContent=idx<25?'Protective conditions currently dominate this illustrative profile':idx<50?'Mixed system conditions: strengthen buffers before pressures accumulate':idx<75?'High environmental pressure in this illustrative profile':'Very high modeled pressure: prioritize material safety, trusted relationships and credible off-ramps';const missing=PROTECTIVE.filter((_,i)=>!$(`.protective[value="${i}"]`)?.checked);$('#protective-moves').innerHTML=(missing.length?missing.slice(0,5):['Maintain and monitor existing protective factors']).map(x=>`<div class="record"><strong>Protective move</strong><p>Increase access to ${esc(x)} using voluntary, culturally appropriate and age-appropriate supports.</p></div>`).join('')}

function initIntegrity(){
 $('#integrity-risks').innerHTML=INTEGRITY_RISKS.map(([id,t])=>`<label class="checkline"><input type="checkbox" value="${id}"> ${esc(t)}</label>`).join('');
}
function runIntegrity(){const selected=$$('#integrity-risks input:checked').map(x=>x.value);const name=$('#integrity-name').value.trim()||'the workflow';const controls={unilateral:'Separate initiation, approval and review for high-consequence decisions; define emergency exception review.',erasable:'Use versioned/tamper-evident records with purpose-limited retention and independent custody.',retaliation:'Provide protected escalation to an independent channel and monitor retaliation indicators separately.',opaque:'Publish decision criteria, exception rules and understandable reasons to affected people.',conflict:'Require conflict-of-interest disclosure, recusal and independent review of exceptions.',noappeal:'Create a practical appeal/correction route with timelines, independent reviewers and outcome explanations.'};$('#integrity-output').innerHTML=(selected.length?selected:['unilateral','opaque','noappeal']).map(k=>`<div class="record"><strong>${esc(name)}</strong><p>${controls[k]}</p></div>`).join('')+`<div class="notice"><strong>Test:</strong> Can an affected person understand who decided, what evidence was used, how to correct an error, and who reviews the reviewer?</div>`;award('integrity',20,1)}

function addSignal(){const count=Number($('#signal-count').value);if(!Number.isFinite(count)||count<0)return;state.signals.unshift({id:crypto.randomUUID?.()||String(Date.now()),category:$('#signal-category').value,count,context:$('#signal-context').value.trim().slice(0,80),created:nowIso()});$('#signal-context').value='';persist();renderSignals();award('signal',15,1)}
function renderSignals(){const list=$('#signal-list');if(!list)return;list.innerHTML=state.signals.length?state.signals.map(s=>`<div class="record"><header><strong>${esc(s.category)}</strong><time>${fmtTime(s.created)}</time></header><p>Magnitude: ${s.count}${s.context?` · ${esc(s.context)}`:''}</p></div>`).join(''):'<p class="muted">No aggregate signals recorded.</p>';const sums={};state.signals.forEach(s=>sums[s.category]=(sums[s.category]||0)+s.count);$('#signal-summary').innerHTML=Object.keys(sums).length?Object.entries(sums).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="record"><strong>${esc(k)}</strong><div class="meter"><i style="width:${Math.min(100,v*8)}%"></i></div><span>${v} aggregated</span></div>`).join(''):'<p class="muted">Add non-identifying counts to see patterns.</p>'}

function initExploitability(){
 $('#exploit-sliders').innerHTML=EXPLOIT_FACTORS.map((f,i)=>`<div class="score-row"><label for="ex-${i}">${esc(f)}</label><input id="ex-${i}" type="range" min="0" max="100" value="35"><output>35</output></div>`).join('');$$('#exploit-sliders input').forEach(x=>x.addEventListener('input',updateExploitability));updateExploitability();
}
function updateExploitability(){const vals=$$('#exploit-sliders input').map(x=>{x.nextElementSibling.value=x.value;return +x.value});const score=Math.round(vals.reduce((a,b)=>a+b,0)/vals.length);$('#exploit-score').textContent=score;$('#exploit-label').textContent=score<30?'Low modeled structural exploitability':score<55?'Moderate structural exploitability':'High structural exploitability: reduce dependency and opacity first';const pairs=vals.map((v,i)=>[v,EXPLOIT_FACTORS[i]]).sort((a,b)=>b[0]-a[0]).slice(0,3);$('#exploit-recommendations').innerHTML=pairs.map(([v,n])=>`<div class="record"><strong>${esc(n)} · ${v}/100</strong><p>${n.includes('gatekeeper')?'Add alternative access, independent escalation and continuity plans.':n.includes('Information')?'Make rules, prices, rights and reasons legible to affected people.':n.includes('authority')?'Separate powers, review exceptions and distribute consequential approvals.':n.includes('scarcity')?'Reduce coercive dependency by improving basic material options and emergency support.':n.includes('isolation')?'Grow trusted networks, peer support and safe outside contact.':n.includes('opacity')?'Expose decision criteria, audit trails and correction channels.':'Create credible grievance routes independent of the authority being challenged.'}</p></div>`).join('')}

function runReward(){const behavior=$('#reward-behavior').value.trim()||'the target pattern';const current=$('#reward-current').value,target=$('#reward-target').value;$('#reward-output').innerHTML=`<div class="record"><strong>1 · Identify the actual payoff</strong><p>${esc(behavior)} currently appears to receive <strong>${esc(current)}</strong>. Verify this with observation rather than assuming motive.</p></div><div class="record"><strong>2 · Reduce amplification</strong><p>Remove avoidable institutional or platform reinforcement while preserving legitimate expression, due process and access.</p></div><div class="record"><strong>3 · Build a substitute route</strong><p>Make <strong>${esc(target)}</strong> a visible, credible path to recognition and belonging.</p></div><div class="record"><strong>4 · Anti-gaming test</strong><p>Check whether the new reward can be captured through performative behavior, favoritism, metrics manipulation or public shaming.</p></div>`;award('reward',15,1)}

const NARRATIVE_PATTERNS=[
 {name:'Collective blame / overgeneralization',re:/\b(all|every|always|never)\b.{0,35}\b(they|them|those people|that group)\b/i,help:'Replace group-wide claims with specific behaviors, actors, times and evidence.'},
 {name:'Dehumanizing or contaminant framing',re:/\b(vermin|parasite|disease|filth|infestation|subhuman)\b/i,help:'Describe concrete conduct without denying human status or dignity.'},
 {name:'Manufactured urgency',re:/\b(now or never|before it is too late|immediately|no time to think|act now)\b/i,help:'Separate genuine deadlines from pressure that blocks verification or deliberation.'},
 {name:'Purity / betrayal framing',re:/\b(pure|traitor|betrayal|real .* only|one of us|enemy within)\b/i,help:'Avoid collapsing disagreement or mixed identity into loyalty tests.'},
 {name:'Revenge / reciprocity loop',re:/\b(payback|revenge|make them suffer|they deserve .* pain|an eye for an eye)\b/i,help:'Ask what repair, boundary or accountability would stop recurrence without propagating retaliation.'},
 {name:'Humiliation as proof',re:/\b(humiliate|embarrass them|shame them|teach them a lesson publicly)\b/i,help:'Distinguish accountability from spectacle or status destruction.'},
 {name:'Secrecy / isolation pressure',re:/\b(don't tell anyone|keep this between us|no outsiders|you can't trust anyone else)\b/i,help:'Check whether secrecy blocks independent advice, support or review.'}
];
function scanNarrative(){const text=$('#narrative-text').value.trim();if(!text){$('#narrative-output').innerHTML='<p class="muted">Paste text to scan.</p>';return}const hits=NARRATIVE_PATTERNS.filter(p=>p.re.test(text));$('#narrative-output').innerHTML=(hits.length?hits.map(h=>`<div class="record"><strong>${esc(h.name)}</strong><p>${esc(h.help)}</p></div>`):['<div class="record"><strong>No configured cues detected</strong><p>This does not mean the text is accurate, safe, harmless or well-sourced. The scanner is intentionally narrow.</p></div>']).join('')+`<div class="notice"><strong>Interpretation boundary:</strong> keyword patterns cannot determine truth, intent, ideology or dangerousness. Use them only as prompts for human review.</div>`;award('narrative',15,1)}
function mutateClaim(){const claim=$('#mutation-claim').value.trim()||'A local program changed its rules.';const steps=[['Source claim',claim],['Compression',`${claim} Details are dropped as the message is shortened for sharing.`],['Identity hook','The change is reframed as something “our side” or “their side” did, increasing social stakes.'],['Motive certainty','Ambiguous reasons are replaced by a confident motive claim without new evidence.'],['Collective blame','Responsibility expands from specific decision-makers to a whole group.'],['Action pressure','The message adds urgency, punishment or retaliation language.'],['Immunity move','Slow the chain: restore the original source, separate fact from inference, name uncertainty, reject group-wide blame, and choose a proportionate response.']];$('#mutation-output').innerHTML=steps.map(([a,b],i)=>`<div class="timeline-item"><div class="step">${i+1}</div><div><strong>${esc(a)}</strong><div class="muted">${esc(b)}</div></div></div>`).join('')}

function addCase(){const id=$('#case-id').value.trim();if(!id)return;state.cases.unshift({id:id.slice(0,40),pattern:$('#case-pattern').value,evidence:$('#case-evidence').value,repair:$('#case-repair').value,created:nowIso()});$('#case-id').value='';persist();renderCases();award('repair',20,1)}
function renderCases(){const el=$('#case-list');if(!el)return;el.innerHTML=state.cases.length?state.cases.map(c=>`<div class="record"><header><strong>${esc(c.id)}</strong><time>${fmtTime(c.created)}</time></header><p>${esc(c.pattern)} · <span class="badge amber">${esc(c.evidence)}</span> · <span class="badge green">${esc(c.repair)}</span></p></div>`).join(''):'<p class="muted">No repair records stored.</p>'}

function initSimulation(){
 $('#simulation-sliders').innerHTML=SIM_VARS.map(([id,label])=>`<div class="score-row"><label for="sim-${id}">${esc(label)}</label><input id="sim-${id}" data-id="${id}" type="range" min="10" max="100" value="50"><output>50</output></div>`).join('');$$('#simulation-sliders input').forEach(x=>x.addEventListener('input',updateSimulation));updateSimulation();
}
function updateSimulation(){const v={};$$('#simulation-sliders input').forEach(x=>{v[x.dataset.id]=+x.value;x.nextElementSibling.value=x.value});const numerator=v.opportunity*v.reward*v.concealment*v.transmission;const denominator=v.friction*v.detection*v.accountability*v.protective;const ratio=numerator/denominator;const index=Math.round(clamp(50*Math.sqrt(ratio),0,100));$('#pressure-index').textContent=index;$('#pressure-interpretation').textContent=index<30?'Low modeled system pressure relative to safeguards':index<55?'Balanced / mixed modeled pressure':index<75?'Elevated modeled pressure: strengthen weakest safeguards':'Very high modeled pressure: prioritize immediate environmental and protective-capacity changes';const weak=[['Protective friction',v.friction],['Detection',v.detection],['Accountability / repair',v.accountability],['Protective capacity',v.protective]].sort((a,b)=>a[1]-b[1]).slice(0,2);$('#pressure-advice').innerHTML=weak.map(([n,val])=>`<div class="record"><strong>${esc(n)} · ${val}</strong><p>Run a targeted design review here before increasing monitoring or punishment elsewhere.</p></div>`).join('')}
function resetSimulation(){$$('#simulation-sliders input').forEach(x=>x.value=50);updateSimulation()}
function runScenario(){const type=$('#scenario-type').value,role=$('#scenario-role').value;const stages=[['Observe','Define the concrete pattern and immediate safety needs without assigning motive or guilt beyond available evidence.'],['Interrupt','Choose the least coercive action that safely interrupts escalation: pause, separation, rate limit, second reviewer, trusted adult, or independent escalation.'],['Preserve','Preserve necessary evidence and context with minimal personal-data collection.'],['Support','Create safe support for affected people and non-harmful off-ramps for participants who can disengage.'],['Review incentives','Ask what attention, status, fear, money, belonging or concealment currently rewards the pattern.'],['Repair','Define restitution, corrective action and future safeguards appropriate to the actual finding and context.'],['Learn','Measure recurrence, false positives, user burden and protective capacity; revise the system rather than declaring the scenario solved.']];$('#scenario-output').innerHTML=`<div class="notice"><strong>Scenario:</strong> ${esc(type)} · <strong>Role:</strong> ${esc(role)}. This rehearsal intentionally omits operational details that could facilitate harm.</div>`+stages.map(([a,b],i)=>`<div class="timeline-item"><div class="step">${i+1}</div><div><strong>${a}</strong><div class="muted">${b}</div></div></div>`).join('');award('simulation',20,1)}

function initEcosystem(){
 $('#ecosystem-sliders').innerHTML=ECO_DOMAINS.map((d,i)=>`<div class="score-row"><label for="eco-${i}">${esc(d)}</label><input id="eco-${i}" data-domain="${esc(d)}" type="range" min="0" max="100" value="50"><output>50</output></div>`).join('');$$('#ecosystem-sliders input').forEach(x=>x.addEventListener('input',updateEcosystem));updateEcosystem();
}
function updateEcosystem(){const vals=$$('#ecosystem-sliders input').map(x=>{x.nextElementSibling.value=x.value;return[+x.value,x.dataset.domain]});const avg=Math.round(vals.reduce((a,b)=>a+b[0],0)/vals.length);$('#ecosystem-score').textContent=avg+'%';$('#ecosystem-gaps').innerHTML=vals.sort((a,b)=>a[0]-b[0]).slice(0,4).map(([v,d])=>`<div class="record"><strong>${esc(d)} · ${v}%</strong><p>Clarify ownership, access, handoffs and the minimum information this domain needs to coordinate safely.</p></div>`).join('');renderEcosystemGraph(vals)}
function renderEcosystemGraph(vals){const svg=$('#ecosystem-graph');if(!svg)return;const cx=450,cy=240,r=175;let h='';vals.forEach(([v,d],i)=>{const a=i/vals.length*Math.PI*2,x=cx+r*Math.cos(a),y=cy+r*Math.sin(a);h+=`<line x1="${cx}" y1="${cy}" x2="${x}" y2="${y}" class="edge ${v>65?'strong':''}" opacity="${.25+v/180}"/><circle cx="${x}" cy="${y}" r="${22+v/8}" class="node-circle"/><text x="${x}" y="${y+4}" text-anchor="middle" fill="currentColor" font-size="10">${esc(d.split(' / ')[0]).slice(0,14)}</text>`});h+=`<circle cx="${cx}" cy="${cy}" r="62" fill="var(--panel2)" stroke="var(--violet)"/><text x="${cx}" y="${cy-3}" text-anchor="middle" fill="currentColor" font-size="13" font-weight="800">Shared protective</text><text x="${cx}" y="${cy+15}" text-anchor="middle" fill="currentColor" font-size="13" font-weight="800">capacity</text>`;svg.innerHTML=h}

function renderStories(){const q=($('#story-search')?.value||'').toLowerCase(),aud=$('#story-audience')?.value||'all';const visible=STORIES.filter(s=>(aud==='all'||s.audience.includes(aud))&&[s.title,s.premise,s.lesson,s.mechanism,s.activity,...s.connection].join(' ').toLowerCase().includes(q));$('#story-list').innerHTML=visible.map((s,i)=>`<article class="panel story-card"><span class="story-num">Story ${String(STORIES.indexOf(s)+1).padStart(2,'0')}</span><h2>${esc(s.title)}</h2><p>${esc(s.premise)}</p><div class="tag-row">${s.audience.map(a=>`<span class="tag">${a}</span>`).join('')}</div><details><summary>Learning architecture</summary><p><strong>System lesson:</strong> ${esc(s.lesson)}</p><p><strong>Why it works:</strong> ${esc(s.mechanism)}</p><p><strong>Activity:</strong> ${esc(s.activity)}</p><p><strong>Connected modules:</strong> ${s.connection.map(x=>`<span class="chip">${esc(x)}</span>`).join(' ')}</p></details><button class="secondary use-story" data-story="${s.id}">Use in workshop</button></article>`).join('')||'<p class="muted">No stories match those filters.</p>';$$('.use-story').forEach(b=>b.addEventListener('click',()=>{ $('#story-select').value=b.dataset.story;location.hash='stories';$('#story-workshop').scrollIntoView({behavior:'smooth'})}))}
function initStorySelect(){$('#story-select').innerHTML=STORIES.map(s=>`<option value="${s.id}">${esc(s.title)}</option>`).join('')}
function translateStory(){const s=STORIES.find(x=>x.id===$('#story-select').value);const audience=$('#story-target').value,context=$('#story-context').value.trim()||'the local context';const stages=[['Hook',`Open with the central dilemma of “${s.title}” in language appropriate for ${audience}. Keep the harmful behavior non-glamorized.`],['Perspective',`Let participants identify what each character believes they are protecting, without equating understanding with approval.`],['System map',`Connect the story to ${s.connection.join(', ')} and map the environmental incentives or inherited scripts involved.`],['Interruption',`Ask where the chain could be interrupted in ${context}: before access, before reward, before imitation, or during repair.`],['Design sprint',s.activity],['Transfer',`Convert one narrative insight into a real but low-risk change in ${context}. Define what evidence would show improvement.`],['Reflection','End with agency: mistakes are consequential, but neither individuals nor communities are required to repeat inherited scripts.']];$('#story-translation').innerHTML=stages.map(([a,b],i)=>`<div class="timeline-item"><div class="step">${i+1}</div><div><strong>${a}</strong><div class="muted">${esc(b)}</div></div></div>`).join('');state.storyRuns.unshift({story:s.id,audience,context,created:nowIso()});persist();award('story',20,2)}

function plannerText(){const setting=$('#planner-setting').value,concern=$('#planner-concern').value,goal=$('#planner-goal').value,constraints=$('#planner-constraints').value.trim(),minData=$('#planner-min-data').checked,repair=$('#planner-repair').checked,youth=$('#planner-youth').checked;const stages=[
 ['1 · Define the system boundary',`Describe the concrete ${concern} pattern in the ${setting} setting. Separate observed behavior, reports, evidence and interpretation. Define who can be affected and what immediate safety obligations already exist.`],
 ['2 · Map the pathway','Trace preparation, access, opportunity, action, concealment, reward and imitation. Mark the two stages where a small design change could create the largest safe interruption.'],
 ['3 · Reduce opportunity','Use safer defaults, separation of powers, least privilege, rate limits, supervision or cooling-off periods only where proportionate. Preserve legitimate and emergency use.'],
 ['4 · Improve visibility','Use aggregate early signals, evidence retention and independent review. A signal should trigger inquiry, not automatic sanction.'],
 ['5 · Reverse harmful rewards','Identify status, money, attention, fear, belonging or concealment rewards. Reduce amplification and create visible pro-social alternatives.'],
 ['6 · Interrupt transmission','Teach narrative immunity, bystander/off-ramp skills and protective norms. Avoid stigma and collective blame.'],
 ['7 · Build protective capacity','Strengthen trusted relationships, material stability, belonging, accessible grievance routes and support services relevant to the setting.'],
 ...(repair?[['8 · Accountability and repair','Keep allegation, finding, restitution, safeguards, recurrence and reintegration separate. Use appropriate professional/legal procedures for serious cases.']]:[]),
 ['9 · Measure without gaming','Track recurrence, interruption, false positives, legitimate-user burden, access to supports and unresolved handoff gaps. Never make “more accusations” a success metric.'],
 ['10 · Review and sunset','Set a review date. Remove controls that add burden without protective value; preserve lessons and evidence needed for accountability, but do not retain personal data indefinitely.']
 ];if(minData)stages.splice(3,0,['Privacy constraint','Collect the minimum personal data needed for the stated purpose; prefer aggregate categories and short retention. Make export, correction and deletion processes visible.']);if(youth)stages.splice(7,0,['Youth co-design','Invite age-appropriate participation focused on “what makes helping easier and asking for help safer?” Never require children to disclose harm publicly to participate.']);const meta=`Goal: ${goal}. Constraints: ${constraints||'none provided'}.`;return{stages,meta,setting,concern,goal}}
function runPlanner(){const p=plannerText();$('#planner-output').innerHTML=`<div class="notice"><strong>${esc(p.meta)}</strong></div>`+p.stages.map(([a,b],i)=>`<div class="timeline-item"><div class="step">${i+1}</div><div><strong>${esc(a)}</strong><div class="muted">${esc(b)}</div></div></div>`).join('');state.plannerRuns.unshift({setting:p.setting,concern:p.concern,goal:p.goal,created:nowIso()});persist();award('planner',30,2)}
function currentPlanText(){return $$('#planner-output .timeline-item').map(x=>`${$('strong',x)?.textContent}\n${$('.muted',x)?.textContent}`).join('\n\n')}

function addEvidence(){const claim=$('#evidence-claim').value.trim();if(!claim)return;state.evidence.unshift({id:crypto.randomUUID?.()||String(Date.now()),claim,type:$('#evidence-type').value,source:$('#evidence-source').value.trim(),status:$('#evidence-status').value,created:nowIso()});$('#evidence-claim').value='';$('#evidence-source').value='';persist();renderEvidence();award('evidence',20,2)}
function renderEvidence(){const el=$('#evidence-list');if(!el)return;const f=$('#evidence-filter')?.value||'all';const rows=state.evidence.filter(e=>f==='all'||e.type===f);el.innerHTML=rows.length?rows.map(e=>`<div class="record"><header><span class="badge ${e.type==='fact'?'green':e.type==='fiction'?'rose':'amber'}">${esc(e.type)}</span><time>${fmtTime(e.created)}</time></header><p><strong>${esc(e.claim)}</strong></p><p class="muted">${e.source?`Source: ${esc(e.source)} · `:''}${esc(e.status)}</p></div>`).join(''):'<p class="muted">No evidence records in this view.</p>'}

function initPromptModules(){$('#prompt-modules').innerHTML=SYSTEMS.map(s=>`<label class="checkline"><input type="checkbox" value="${s.id}" checked> ${esc(s.name)}</label>`).join('')}
function generatePrompt(){const mods=$$('#prompt-modules input:checked').map(x=>SYSTEMS.find(s=>s.id===x.value));const objective=$('#prompt-objective').value.trim(),deployment=$('#prompt-deployment').value;const text=`# Safeguarding Next-Gen Implementation Prompt\n\n## Objective\n${objective}\n\n## Deployment\n${deployment}\n\n## Non-negotiable doctrine\n- Model systems, workflows, environments and protective capacity; do not create person-level dangerousness or guilt scores.\n- Separate allegation, evidence, inference, adjudication, repair and recurrence.\n- Privacy by design: minimum necessary data, explicit retention, no hidden telemetry, visible export/import and correction.\n- Preserve legitimate dissent, due process, accessibility and human agency.\n- Core functionality must work deterministically without AI or multiplayer.\n- Optional capabilities must fail gracefully.\n- Label facts, inference, hypotheses, simulations, metaphors and fiction.\n\n## Required modules\n${mods.map((m,i)=>`${i+1}. ${m.name}\n   - Purpose: ${m.summary}\n   - Mechanism: ${m.mechanism}\n   - Safeguards: ${m.safeguards.join(' ')}`).join('\n')}\n\n## Shared shell\nUse one semantic route registry to drive sticky top navigation, collapsible side navigation, breadcrumbs, deep links and active states. Include global search, responsive drawers, keyboard/focus management, light/dark themes, reduced motion, print CSS and a no-JS reference fallback.\n\n## Data architecture\nUse IndexedDB for structured durable local state and localStorage only for small preferences. Include schemaVersion, migration hooks, validated JSON import/export, selective reset, clear storage-status indicators and failure handling. Never imply cross-device sync unless implemented.\n\n## Offline/PWA\nWhen hosted over HTTPS/localhost, use a versioned service worker to precache the app shell. Explain that file:// cannot use service workers. Offline mode must preserve essential reading, planning and local tools; live collaboration and external APIs may be unavailable.\n\n## Collaboration\nKeep transport schemas independent. Same-origin/local collaboration may use BroadcastChannel; internet collaboration must be explicit and should not transmit sensitive safeguarding records by default. Production institutional deployments require durable authorization, membership, moderation, abuse controls and recovery beyond ad-hoc P2P.\n\n## Deterministic planner\nImplement: intent classification -> system lever selection -> dependency rules -> privacy constraints -> intervention patterns -> failure modes -> staged implementation -> measurement -> review/sunset. Results should be reproducible from the same inputs.\n\n## Verification\nTest routing, search, keyboard use, focus, storage, export/import, offline degradation, malformed input handling, mobile layout and optional-feature failure. Do not claim a test passed unless it was executed.\n\n## Deliverable\nReturn working files, file tree, deployment notes, known limitations, Zero-Harm/Anti-Inversion note, and Attributions & Licenses.`;$('#prompt-output').value=text;award('prompt',15,1)}

function renderGuides(){$('#guide-list').innerHTML=GUIDES.map((g,i)=>`<article class="panel"><p class="eyebrow">Guide ${String(i+1).padStart(2,'0')}</p><h2>${esc(g.title)}</h2><details open><summary>One-minute explanation</summary><p>${esc(g.one)}</p></details><details><summary>Actionable steps</summary><ol>${g.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></details><details><summary>Advanced concepts</summary><p>${esc(g.advanced)}</p></details><details><summary>Implementation notes</summary><p>${esc(g.impl)}</p></details></article>`).join('')}

function capability(name,ok,detail){return`<div class="diag"><strong>${esc(name)}</strong><span class="badge ${ok?'green':'rose'}">${ok?'available':'unavailable'}</span><small>${esc(detail||'')}</small></div>`}
async function runDiagnostics(){const grid=$('#capability-grid');const caps=[];caps.push(['IndexedDB','indexedDB'in window,'structured local storage']);caps.push(['Service Worker','serviceWorker'in navigator,location.protocol==='file:'?'browser supports it, but file:// cannot register':'host-dependent PWA cache']);caps.push(['BroadcastChannel','BroadcastChannel'in window,'same-origin tab collaboration']);caps.push(['WebRTC','RTCPeerConnection'in window,'peer transport primitive']);caps.push(['WebGPU','gpu'in navigator,'optional local GPU compute']);caps.push(['WebCrypto',!!crypto?.subtle,'hashing and cryptographic primitives']);caps.push(['Storage estimate',!!navigator.storage?.estimate,'quota diagnostics']);caps.push(['File API','FileReader'in window,'JSON import']);caps.push(['Clipboard',!!navigator.clipboard,'secure-context copy convenience']);caps.push(['Online status','onLine'in navigator,navigator.onLine?'currently online':'currently offline']);grid.innerHTML=caps.map(x=>capability(...x)).join('');const tests=[];try{localStorage.setItem('sng-test','1');localStorage.removeItem('sng-test');tests.push(['Preference storage','pass','localStorage write/read path available'])}catch(e){tests.push(['Preference storage','fail',e.message])}try{await DB.set('selftest',{t:Date.now()});const v=await DB.get('selftest');tests.push(['IndexedDB round trip',v?.t?'pass':'fail',v?.t?'write/read succeeded':'round trip returned no value'])}catch(e){tests.push(['IndexedDB round trip','fail',e.message])}try{const json=JSON.stringify({schemaVersion:1});JSON.parse(json);tests.push(['JSON portability','pass','serialization and parse succeeded'])}catch(e){tests.push(['JSON portability','fail',e.message])}try{const d=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('safeguarding-nextgen'));tests.push(['SHA-256','pass',`${d.byteLength*8}-bit digest produced`])}catch(e){tests.push(['SHA-256','fail',e.message])}$('#test-results').innerHTML=tests.map(([n,s,d])=>`<div class="record"><strong>${esc(n)} · <span class="badge ${s==='pass'?'green':'rose'}">${s}</span></strong><p>${esc(d)}</p></div>`).join('');award('diagnostics',10,1)}
async function analyzeHardware(){const gpu='gpu'in navigator,mem=navigator.deviceMemory||null,cores=navigator.hardwareConcurrency||null,known=Number($('#known-vram').value)||null,work=$('#ai-workload').value;let cls='small (roughly sub-2B quantized class)';if((known&&known>=8)||(mem&&mem>=16))cls='medium (roughly 2B–4B quantized class)';if((known&&known>=12)&&(mem&&mem>=16))cls='larger local class may be practical, but benchmark before committing';if(!gpu)cls='WebGPU unavailable: prefer deterministic tools or CPU/WASM-specific models';const lines=[`WebGPU: ${gpu?'available':'not exposed'}`,`navigator.deviceMemory: ${mem??'not reported'} GB`, `logical CPU cores: ${cores??'not reported'}`,`user-entered VRAM: ${known??'not provided'} GB`,`workload: ${work}`,`conservative recommendation: ${cls}`,'','This is a heuristic hardware class recommendation, not a guarantee that any specific model/runtime will load. Browser GPU drivers, context size and model format materially affect memory use.'];$('#hardware-output').textContent=lines.join('\n')}

function renderHud(){const {level,cur}=levelInfo();$('#hud-level').textContent=level;$('#hud-seeds').textContent=state.progress.seeds;$('#xp-fill').style.width=cur+'%';$('#xp-label').textContent=`${cur} / 100 XP`;$('#record-count').textContent=recordCount();$('#last-saved').textContent=state.lastSaved?fmtTime(state.lastSaved):'Not saved yet';const quests=[['planner','Run a safeguarding plan',30],['story','Translate a story to action',20],['evidence','Add a provenance record',20],['simulation','Rehearse a scenario',20],['diagnostics','Run capability checks',10],['export','Export your workspace',10]];$('#quest-list').innerHTML=quests.map(([id,t,xp])=>`<div class="quest ${state.progress.quests[id]?'done':''}"><span>${state.progress.quests[id]?'✓':'○'}</span><div>${esc(t)}</div><small>+${xp} XP</small></div>`).join('')}

function workspaceExport(){return{app:'Safeguarding Next-Gen OS',exportedAt:nowIso(),...state}}
function exportState(){downloadText(`safeguarding-nextgen-workspace-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(workspaceExport(),null,2),'application/json');award('export',10,1)}
async function importState(file){try{const raw=JSON.parse(await file.text());if(!raw||typeof raw!=='object'||Number(raw.schemaVersion)!==1)throw new Error('Unsupported or missing schemaVersion');const arrays=['signals','cases','evidence','plannerRuns','storyRuns'];for(const a of arrays)if(raw[a]!==undefined&&!Array.isArray(raw[a]))throw new Error(`${a} must be an array`);state=mergeState(raw);await persist(true);renderAll();alert('Workspace imported successfully.')}catch(e){alert(`Import failed: ${e.message}`)}}

function updateConnectivity(){const online=navigator.onLine;$('#online-dot').className='dot '+(online?'online':'offline');$('#online-label').textContent=online?'Online':'Offline';$('#pwa-label').textContent=location.protocol==='file:'?'Local file mode · service worker unavailable':('serviceWorker'in navigator?'PWA capable · hosted mode':'Service worker unsupported')}
async function registerSW(){if(location.protocol==='file:'||!('serviceWorker'in navigator))return;try{await navigator.serviceWorker.register('./sw.js')}catch(e){console.warn('SW registration failed',e)}}

function joinLocalRoom(){leaveRoom();const id=slug($('#room-id').value)||'safeguarding-nextgen-demo';if(!('BroadcastChannel'in window)){setRoomStatus('BroadcastChannel unavailable in this browser.');return}roomChannel=new BroadcastChannel(`sng:${id}`);roomChannel.onmessage=e=>receiveRoom(e.data,'local peer');setRoomStatus(`Joined same-origin room “${id}”. Open another tab on this same site to collaborate.`);$('#send-room').disabled=false;logRoom('system','Joined local tab room. No data leaves this origin through BroadcastChannel.')}
function setRoomStatus(t){$('#room-status').textContent=t}
function logRoom(who,msg){const div=document.createElement('div');div.className='record';div.innerHTML=`<header><strong>${esc(who)}</strong><time>${new Date().toLocaleTimeString()}</time></header><p>${esc(msg)}</p>`;$('#room-log').prepend(div)}
function receiveRoom(data,peer){if(!data||data.type!=='chat')return;logRoom(data.name||peer,data.message||'')}
function sendRoom(){const message=$('#room-message').value.trim();if(!message)return;const data={type:'chat',name:$('#display-name').value.trim()||'Steward',message:message.slice(0,1200),at:Date.now()};if(roomChannel)roomChannel.postMessage(data);if(p2pSend)try{p2pSend(data)}catch(e){logRoom('system',`P2P send failed: ${e.message}`)}logRoom(data.name,data.message);$('#room-message').value=''}
function leaveRoom(){try{roomChannel?.close()}catch{}roomChannel=null;try{p2pRoom?.leave()}catch{}p2pRoom=null;p2pSend=null;$('#send-room')&&( $('#send-room').disabled=true);setRoomStatus('Not connected.')}
async function joinInternetRoom(){if(!navigator.onLine){setRoomStatus('Offline: internet peer mode unavailable.');return}try{setRoomStatus('Loading optional Trystero adapter…');const mod=await import('https://cdn.jsdelivr.net/npm/trystero@0.25.3/+esm');const id=slug($('#room-id').value)||'safeguarding-nextgen-demo';p2pRoom=mod.joinRoom({appId:'safeguarding-nextgen-os-v1'},id);const [send,get]=p2pRoom.makeAction('chat');p2pSend=send;get((data,peerId)=>receiveRoom(data,peerId));p2pRoom.onPeerJoin?.(peer=>logRoom('system',`Peer joined: ${peer.slice(0,8)}…`));p2pRoom.onPeerLeave?.(peer=>logRoom('system',`Peer left: ${peer.slice(0,8)}…`));setRoomStatus(`Joined optional internet P2P room “${id}”. Do not share sensitive case data.`);$('#send-room').disabled=false;logRoom('system','Internet P2P enabled by explicit user action. Discovery infrastructure may observe the room identifier.')}catch(e){setRoomStatus(`Internet P2P unavailable: ${e?.message||String(e)}. Core/local collaboration still works.`)}}

function searchIndex(){const items=[];ROUTES.forEach(r=>items.push({title:r.label,text:r.label,hash:r.id,type:'Module'}));SYSTEMS.forEach(s=>items.push({title:s.name,text:[s.summary,s.mechanism,...s.tags].join(' '),hash:s.id,type:'System'}));STORIES.forEach(s=>items.push({title:s.title,text:[s.premise,s.lesson,s.activity,...s.connection].join(' '),hash:'stories',type:'Story'}));GUIDES.forEach(g=>items.push({title:g.title,text:[g.one,...g.steps,g.advanced,g.impl].join(' '),hash:'guides',type:'Guide'}));return items}
function updateGlobalSearch(){const q=$('#global-search').value.toLowerCase().trim();const rows=q?searchIndex().map(x=>({...x,score:(x.title.toLowerCase().includes(q)?3:0)+(x.text.toLowerCase().includes(q)?1:0)})).filter(x=>x.score).sort((a,b)=>b.score-a.score).slice(0,30):searchIndex().slice(0,12);$('#search-results').innerHTML=rows.map(x=>`<a class="search-result" href="#${x.hash}"><strong>${esc(x.title)}</strong><br><small>${esc(x.type)}</small></a>`).join('')}
function openSearch(){document.body.classList.remove('drawer-open');$('#search-modal').classList.add('open');$('#global-search').focus();updateGlobalSearch()}
function closeSearch(){$('#search-modal').classList.remove('open');$('#global-search-button').focus()}

function renderAll(){renderSystems();renderSignals();renderCases();renderEvidence();renderHud();renderStories();updateConnectivity()}

function initEvents(){
 window.addEventListener('hashchange',routeFromHash);window.addEventListener('online',updateConnectivity);window.addEventListener('offline',updateConnectivity);
 $('#drawer-toggle').addEventListener('click',()=>{const on=document.body.classList.toggle('drawer-open');$('#drawer-toggle').setAttribute('aria-expanded',String(on))});$('#drawer-backdrop').addEventListener('click',()=>document.body.classList.remove('drawer-open'));$('#right-drawer-toggle').addEventListener('click',()=>document.body.classList.toggle('right-drawer-open'));
 $('#theme-toggle').addEventListener('click',()=>{const v=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=v;localStorage.setItem('sng-theme',v)});$('#motion-toggle').addEventListener('click',()=>{document.documentElement.classList.toggle('reduce-motion');localStorage.setItem('sng-motion',document.documentElement.classList.contains('reduce-motion')?'reduced':'normal')});
 $('#system-search').addEventListener('input',renderSystems);$('#expand-systems').addEventListener('click',()=>$$('#system-list details').forEach(d=>d.open=true));$('#collapse-systems').addEventListener('click',()=>$$('#system-list details').forEach(d=>d.open=false));
 $('#run-friction').addEventListener('click',runFriction);$('#run-integrity').addEventListener('click',runIntegrity);$('#add-signal').addEventListener('click',addSignal);$('#clear-signals').addEventListener('click',()=>{if(confirm('Clear all local aggregate signals?')){state.signals=[];persist();renderSignals()}});$('#run-reward').addEventListener('click',runReward);$('#scan-narrative').addEventListener('click',scanNarrative);$('#mutate-claim').addEventListener('click',mutateClaim);$('#add-case').addEventListener('click',addCase);$('#clear-cases').addEventListener('click',()=>{if(confirm('Clear the local restorative ledger?')){state.cases=[];persist();renderCases()}});$('#reset-simulation').addEventListener('click',resetSimulation);$('#run-scenario').addEventListener('click',runScenario);
 $('#story-search').addEventListener('input',renderStories);$('#story-audience').addEventListener('change',renderStories);$('#translate-story').addEventListener('click',translateStory);$('#run-planner').addEventListener('click',runPlanner);$('#copy-plan').addEventListener('click',()=>copyText(currentPlanText()));$('#download-plan').addEventListener('click',()=>downloadText('safeguarding-plan.txt',currentPlanText()));
 $('#add-evidence').addEventListener('click',addEvidence);$('#evidence-filter').addEventListener('change',renderEvidence);$('#join-local-room').addEventListener('click',joinLocalRoom);$('#join-internet-room').addEventListener('click',joinInternetRoom);$('#leave-room').addEventListener('click',leaveRoom);$('#send-room').addEventListener('click',sendRoom);
 $('#generate-prompt').addEventListener('click',generatePrompt);$('#copy-prompt').addEventListener('click',()=>copyText($('#prompt-output').value));$('#download-prompt').addEventListener('click',()=>downloadText('safeguarding-master-prompt.md',$('#prompt-output').value,'text/markdown'));
 $('#rerun-tests').addEventListener('click',runDiagnostics);$('#analyze-hardware').addEventListener('click',analyzeHardware);$('#export-state').addEventListener('click',exportState);$('#import-state').addEventListener('change',e=>{const f=e.target.files?.[0];if(f)importState(f);e.target.value=''});$('#download-compendium').addEventListener('click',()=>downloadText('safeguarding-nextgen-chat-compendium.md',`Safeguarding Next-Gen\n\n${SYSTEMS.map((s,i)=>`${i+1}. ${s.name}\n${s.summary}`).join('\n\n')}\n\nStories\n\n${STORIES.map((s,i)=>`${i+1}. ${s.title}\n${s.premise}`).join('\n\n')}`,'text/markdown'));
 $('#global-search-button').addEventListener('click',openSearch);$('#close-search').addEventListener('click',closeSearch);$('#global-search').addEventListener('input',updateGlobalSearch);$('#search-modal').addEventListener('click',e=>{if(e.target.id==='search-modal')closeSearch()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#search-modal').classList.contains('open'))closeSearch();document.body.classList.remove('drawer-open','right-drawer-open')}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}})
}

function initSplash(){const splash=$('#splash'),bar=$('#splash-progress'),status=$('#splash-status'),enter=$('#enter-app'),skip=$('#skip-splash');let done=false,p=8,timer=null,hard=null;const close=(immediate=false)=>{if(done)return;done=true;if(timer)clearInterval(timer);if(hard)clearTimeout(hard);if(skip.checked)try{localStorage.setItem('sng-skip-splash','1')}catch{}bar.style.width='100%';status.textContent='Workspace ready.';if(immediate){splash.classList.add('hidden')}else setTimeout(()=>splash.classList.add('hidden'),180)};enter.addEventListener('click',()=>close());let stored=false;try{stored=localStorage.getItem('sng-skip-splash')==='1'}catch{};if(stored){close(true);return}const msgs=['Loading prevention levers…','Linking protective systems…','Preparing story engines…','Checking local storage…','Opening workspace…'];timer=setInterval(()=>{p=Math.min(92,p+8);bar.style.width=p+'%';status.textContent=msgs[Math.min(msgs.length-1,Math.floor(p/20))]},280);hard=setTimeout(()=>close(),7000);setTimeout(()=>close(),2200)}

async function boot(){
 try{const t=localStorage.getItem('sng-theme');if(t)document.documentElement.dataset.theme=t;if(localStorage.getItem('sng-motion')==='reduced')document.documentElement.classList.add('reduce-motion')}catch{}
 renderNav();renderOverview();initFriction();initIntergenerational();initIntegrity();initExploitability();initSimulation();initEcosystem();initStorySelect();initPromptModules();renderGuides();initEvents();initSplash();updateConnectivity();registerSW();
 try{await DB.open();const saved=await DB.get('workspace');if(saved)state=mergeState(saved)}catch(e){console.warn('IndexedDB unavailable; session remains usable without durable DB',e)}
 renderAll();routeFromHash();runDiagnostics();
}

document.addEventListener('DOMContentLoaded',boot);
